package com.landosol.toolbox.clanbattle.recognition

import android.graphics.BitmapFactory
import android.util.Base64
import java.security.MessageDigest

data class LoadedControlTemplates(
    val controls: BattleControlTemplates,
    val menu: PixelImage,
)

internal data class EmbeddedControlTemplate(
    val sha256: String,
    val base64: String,
)

object EmbeddedControlTemplateLoader {
    fun load(): LoadedControlTemplates = LoadedControlTemplates(
        controls = BattleControlTemplates(
            autoOn = loadImage("auto_on"),
            autoOff = loadImage("auto_off"),
            globalSetOn = loadImage("set_on"),
            globalSetOff = loadImage("set_off"),
            roleSetOn = loadImage("role_set_on"),
        ),
        menu = loadImage("menu"),
    )

    private fun loadImage(name: String): PixelImage {
        val source = encodedTemplates.getValue(name)
        val bytes = Base64.decode(source.base64, Base64.DEFAULT)
        require(bytes.sha256() == source.sha256) { "会战控制模板校验失败：$name" }
        val bitmap = requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size)) {
            "会战控制模板无法解码：$name"
        }
        val pixels = IntArray(bitmap.width * bitmap.height)
        bitmap.getPixels(pixels, 0, bitmap.width, 0, 0, bitmap.width, bitmap.height)
        return PixelImage(bitmap.width, bitmap.height, pixels).also { bitmap.recycle() }
    }

    private fun ByteArray.sha256(): String = MessageDigest.getInstance("SHA-256")
        .digest(this)
        .joinToString("") { "%02x".format(it) }

    internal val encodedTemplates = mapOf(
        "auto_on" to EmbeddedControlTemplate(
            sha256 = "68c4989e8792b6cb4e19cd1e0cdf6242ce324d56acb8b11b13e074355fd6926c",
            base64 = "",
        ),
        "auto_off" to EmbeddedControlTemplate(
            sha256 = "e20d1bc96876acda9a7f62bb51d5f597d6120011fc4a893db354a51da3d5d181",
            base64 = "",
        ),
        "set_on" to EmbeddedControlTemplate(
            sha256 = "0213c5e641f87ec0ad766693a987f93d0468886c515032e87a364ef3565cd369",
            base64 = "",
        ),
        "set_off" to EmbeddedControlTemplate(
            sha256 = "eaf054c2324257e7b910558091f390ec6090fa07539085bbfd2203dd4ce37760",
            base64 = "",
        ),
        "role_set_on" to EmbeddedControlTemplate(
            sha256 = "6189ae5c9f43968a32403f34e6254fa9249e5a1b0dac6c63b732f91cb12de503",
            base64 = "",
        ),
        "menu" to EmbeddedControlTemplate(
            sha256 = "15b43ac9e8ae68b028492c1460d2260b6d6b19c77563b0188d5c0357b64b9257",
            base64 = "",
        ),
    )
}
